# -*- coding: utf-8 -*-
# Обновление системного промта kip8test до post-Task 317
# (штамп «данные от» → тултип кнопки «Обновить»; кнопки в три ряда
#  ровно в высоту окон; зазоры 3px; рамки бара 5px)
with open('Системный_промт_для_приложения_КИПиА.md', encoding='utf-8') as f:
    lines = f.readlines()

new3 = '''> **Версия документа:** 2026-09-04 (post-Task 317: ШТАМП «ДАННЫЕ ОТ…» УБРАН ИЗ БАРА — ЖИВЁТ В ИНФОРМАЦИОННОМ ОКНЕ КНОПКИ «ОБНОВИТЬ» (появляется при НАВЕДЕНИИ мыши/по фокусу; позиция над кнопкой, не хватает места — под ней; дата #wsRefreshTipDate обновляется живьём, описание кнопки — бывший title — второй строкой; скрытие: уход курсора/потеря фокуса/клик/прокрутка — capture-фаза; pointer-events: none, z-index 9450); ВСЕ КНОПКИ — ТРИ РЯДА РОВНО В ВЫСОТУ ОКОН СПРАВА: строки 2/3 переехали ВНУТРЬ колонки кнопок .ws-toolbar-main (было: отдельные ряды бара во всю ширину), колонка height 95px = окна, каждый ряд calc((95px − 6px)/3) ≈ 29.7px + два зазора 3px = ровно 95px (border-box), кнопки/селекты height 100% + padding 4px 12px, nowrap/stretch/overflow hidden; скрытый ряд (нет правок/нет права) габаритов кнопок НЕ меняет — пустой слот, сетка под баром не прыгает; РАССТОЯНИЕ МЕЖДУ РЯДАМИ КНОПОК — 3px; РАМКИ БАРА — 5px со всех сторон и НЕ ИЗМЕНЯЮТСЯ (проверено: единственное правило .ws-toolbar с padding — 5px); мобильный: колонка кнопок (3 ряда, gap 3px) → окна, кнопки 34px; высота бара 106px = 95 + 2×5 + 1. Сервер/листы/Apps Script НЕ менялись. Тесты: 1629 → 1650/0 (+21 test-task317.js; актуализированы test-task315 [строки 2/3 внутри колонки], test-task314 [штамп → тултип], test-work-schedule/test-prod-calendar [media-правила]; SW-бамп v555→v556 в 17 тест-файлах + sw.js). Верификация: task317-browser-check.py 49/49 (4 контекста: десктоп-Админ 1280 [рамки 5px; высота бара 106; три части равные ±8px; колонка=окна=95.0±0.6; ряды 29.67; зазоры 3.0; кнопки во всю высоту без переполнений; штампа в DOM нет; тултип: hover → показан с «данные от…» + описание, над кнопкой, pointer-events none, лево по кнопке; уход → скрыт; фокус → показан; прокрутка окна мероприятий → скрыт; клик → закрыт + тост; правка → ряд 2 внутри колонки, высоты/зазоры те же, последний ряд ровно у низа окон, сетка НЕ прыгает; отмена → ряд 2 скрыт, сетка на месте; светлая — тултип #fbf8f0, колонка 95], зритель [ряды 2/3 скрыты, ряд 1 наверху, колонка 95, кнопка не растянута, тултип работает], мобильный 375 [колонка, кнопки 34px, зазор 3px, рамки 5px], 1024px [колонка 95, ряд 1 одной строкой — 310px < 332px, переполнений нет]; 0 JS-ошибок во всех контекстах); регресс 298 34/34, 303 20/20, 304 10/10, 305 20/20, 306 29/29 (I2 актуализирован — кнопки по рядам колонки; ×2), 307 20/20, 308 20/20, 309 26/26, 310 20/20, 311 24/24, 312 31/31, 313 30/30, 314 36/36 (B3/C5/G2/H/H2 актуализированы — дата в тултипе), 315 33/33 (G3/L3 актуализированы — ряды в колонке), 316 28/28; VLM ×3 (rows/mobile подтверждены; замечание tooltip-скрина опровергнуто численными измерениями). ПЕРЕНОС В kip8: НЕ выполнен — Task 317 ожидает проверки пользователем в kip8test (после проверки — одним коммитом вместе с 315+316, kip8 v417→v418). Деплой пользователя: GitHub Pages + Ctrl+Shift+R ×1–2; Apps Script НЕ трогать.)
'''

assert lines[2].startswith('> **Версия документа:**')
lines.insert(2, new3 if new3.endswith('\n') else new3 + '\n')
print('Строка 3 вставлена (цепочка версий)')

src = ''.join(lines)

reps = [
    ('> **Текущая версия кэша:** `kipia-test-v555`',
     '> **Текущая версия кэша:** `kipia-test-v556`'),
    ('| `kip8test` | PWA | `kipia-test-v555` |',
     '| `kip8test` | PWA | `kipia-test-v556` |'),
]
for old, new in reps:
    n = src.count(old)
    assert n == 1, (old, n)
    src = src.replace(old, new)
print('Версии кэша обновлены (2 замены)')

# Счётчики тестов
reps2 = [
    ('├── tests/                      # 1629 юнит-тестов (Node.js, 34 файлов): run-all.js, test-role-access.js, и др.',
     '├── tests/                      # 1650 юнит-тестов (Node.js, 35 файлов): run-all.js, test-role-access.js, и др.'),
    ('ожидается `1629 passed, 0 failed`', 'ожидается `1650 passed, 0 failed`'),
    ('# Ожидается: 1629 passed, 0 failed', '# Ожидается: 1650 passed, 0 failed'),
]
for old, new in reps2:
    n = src.count(old)
    assert n == 1, (old, n)
    src = src.replace(old, new)
print('Счётчики тестов обновлены (3 замены)')

# Буллет Task 317 — после буллета Task 316 (новые задачи ниже)
entry = ('\n- **График работы — тултип «данные от…» кнопки «Обновить» + кнопки тремя рядами ровно в высоту окон (Task 317)**: '
         'по заявке пользователя: «Строку "данные от" после кнопки "Обновить" убрать в информационное окно, появляющееся при наведении указателя мыши на кнопку "Обновить". Габариты кнопок в баре нужно сделать, чтобы все кнопки в три ряда помещались ровно в высоту окон справа от них, и расстояние между рядами кнопок должно быть 3px. Рамки от границ бара до его внутренних элементов должны быть 5px и не изменяться». 1) ТУЛТИП: штамп #wsCacheStamp (Task 314, занимал место в ряду 1) УДАЛЁН; НОВОЕ #wsRefreshTip (.ws-refresh-tip, fixed, z-index 9450, pointer-events: none — клики сквозь, max-width 300px, [hidden] → display: none, тёмный bg-tertiary/светлый #fbf8f0): показ при НАВЕДЕНИИ (mouseenter) и по ФОКУСУ с клавиатуры (focus), скрытие — mouseleave/blur/клик (через 120мс — итог покажет тост)/прокрутка (document-scroll в CAPTURE-фазе — ловит и скролл окон бара — fixed-позиция устаревает); позиция — НАД кнопкой (r.top − h − 8), сверху < 4px — ПОД ней (r.bottom + 6), лево по кнопке (min 6px); содержимое: строка-дата «данные от ДД.ММ, ЧЧ:ММ» (#wsRefreshTipDate, жирная, _updateCacheStamp пишет СВЕЖУЮ дату при каждом показе и обновляет живьём — «Обновить» под курсором обновляет строку) + описание кнопки (бывший нативный title — вторичная мелкая строка, переносится); БЕЗ данных — «локальных данных ещё нет»; нативный title кнопки УДАЛЁН (не двойное окно); на мобиле тултип не мешает (клик сразу прячет). 2) ТРИ РЯДА КНОПОК = ВЫСОТА ОКОН: строки 2 (.ws-actions-row «Сохранить»/«Отменить») и 3 (.ws-generate-row «Сформировать») ПЕРЕЕХАЛИ внутрь колонки кнопок .ws-toolbar-main (было Task 315: отдельные ряды бара во всю ширину ПОД окнами); колонка — flex column, gap 3px (РАССТОЯНИЕ МЕЖДУ РЯДАМИ — 3px, заявка); на десктопе (media ≥1024px) колонка height: 95px = РОВНО высота окон справа (окна 95px с Task 270), каждый ряд height: calc((95px − 6px)/3) ≈ 29.7px + два зазора 3px = ровно 95px (border-box глобальный): три ряда кнопок занимают РОВНО высоту окон (последний ряд у самого низа); кнопки/селекты — height 100% (во всю высоту ряда) + компактнее padding 4px 12px (текст 14px входит), nowrap, align-items: stretch, overflow: hidden у рядов (высота не нарушается); СКРЫТЫЙ ряд (нет несохранённых правок / нет права записи) габаритов кнопок НЕ меняет — ряды фиксированной высоты, освободившийся слот остаётся пустым, колонка всегда 95px → сетка под баром НЕ прыгает при появлении/скрытии ряда 2 (проверено численно: gridY до/после правки совпадает); ряд 1 в обёртке .ws-toolbar-row #wsSelectsRow (месяц/год/«Обновить», на мобиле wrap, на десктопе nowrap — 310px < 332px трети при 1024px); ВЫСОТА БАРА: 95 + 2×5 + 1 = 106px (было ~145: строки 2/3 добавляли высоту). 3) РАМКИ БАРА 5px: .ws-toolbar padding: 5px (Task 270) — НЕ меняется ни в одной теме/брейкпоинте (проверено перебором правил: единственное .ws-toolbar с padding — 5px). 4) МОБАЙЛ: колонка кнопок (3 ряда, gap 3px, кнопки 34px) → окна мероприятий/календаря под ней (базовые правила, media выключен). Сервер WorkSchedule.gs/листы/Apps Script/кэш/refreshData/«Сохранить»/«Отменить»/«Сформировать»/окна — НЕ менялись (refreshData — прежний; _updateCacheStamp пишет в #wsRefreshTipDate вместо удалённого #wsCacheStamp). Верификация: сьют 1629→1650/0 (+21 tests/test-task317.js: HTML [колонка 3 рядов, тултип, штамп удалён, title удалён], CSS [column+gap 3px, height 95px, calc((95−6)/3), nowrap/stretch, height 100%+padding 4px, [hidden], тултип fixed/pe none/z-index 9450/светлая, рамки 5px перебором правил], JS [_updateCacheStamp → wsRefreshTipDate + «локальных данных ещё нет»; _showRefreshTip: над/под кнопкой; _hideRefreshTip; init слушатели mouseenter/mouseleave/focus/blur/click/scroll-capture; loadGrid 3 ветки], VM [формат даты, подсказка, позиция 152/56, скрытие], SW v556; актуализированы: test-task315 [строки 2/3 внутри колонки — iMain < iAct; assertFalse v557], test-task314 [штамп → тултип: HTML/CSS/VM, mkDoc wsRefreshTipDate], test-work-schedule [media .ws-toolbar-main height 95px, база column+gap 3px, wrap у .ws-toolbar-row], test-prod-calendar [media height 95px]; SW-бамп v555→v556 в sw.js + 17 тест-файлах), task317-browser-check.py 49/49 (порт 8937, 4 контекста: десктоп-Админ 1280×800 — computed padding бара 5px, высота бара 106 (была 145); три части равные (макс−мин ≤ 8px); колонка=окна=календарь=95.0±0.6; ряды 29.67±0.6; зазор между рядами 3.0±0.6 (и через скрытый слот); ряд 3 в пределах колонки; кнопки во всю высоту ряда, переполнений (scrollHeight) нет; штампа в DOM нет, тултип hidden; hover: показан, «данные от …» + описание, над кнопкой, лево по кнопке, pointer-events none; уход курсора → скрыт; фокус → показан, blur → скрыт; прокрутка окна мероприятий (реальный scroll-событие, capture) → скрыт; клик «Обновить» → тултип закрылся + тост «Данные графика обновлены»; правка ячейки (попап → «Н») → ТРИ ряда в колонке, ряд 2 внутри (ширина = колонке, не бар), высоты 29.67/зазоры 3, последний ряд ровно у низа колонки, колонка/бар/сетка НЕ изменились; «Отменить» → ряд 2 скрыт, сетка на месте; светлая тема — тултип rgb(251,248,240), колонка 95; 0 JS-ошибок; зритель «ИТР8 pro» — только ряд 1, колонка 95, кнопка НЕ растянута (не 95px!), тултип работает; мобильный 375×812 — бар колонкой, ряды/окна вертикально, кнопки 34px, зазор 3px, рамки 5px; вьюпорт 1024 — колонка 95, ряд 1 одной строкой (310 < 332), переполнений нет), регресс браузером: 298 34/34, 303 20/20, 304 10/10, 305 20/20, 306 29/29 (I2 — «Обновить» в ряду 1 .ws-toolbar-row; ×2), 307 20/20, 308 20/20, 309 26/26, 310 20/20, 311 24/24, 312 31/31, 313 30/30, 314 36/36 (B3/C5/G2/H/H2 — дата в тултипе #wsRefreshTipDate), 315 33/33 (G3 — ряд 2 ВНУТРИ колонки; L3 — «Сформировать» НАД окнами в кнопочном блоке), 316 28/28; VLM ×3 (3-ряда: все ряды видны, последний ровно у низа окон, «данные от» только в тултипе, без переполнений; мобайл: колонка, кнопки целы, окна аккуратно; tooltip-скрин — замечание «неравные части» опровергнуто численными замерами ±8px). SW kipia-test-v555→v556. ДЕПЛОЙ: только фронтенд — GitHub Pages + Ctrl+Shift+R ×1–2; Apps Script НЕ трогать — см. scripts/DEPLOY-Task317-tooltip-three-rows.md')
lines2 = src.split('\n')
insert_at = None
for i, l in enumerate(lines2):
    if l.startswith('- **График работы — наведение/клик на дату шапки'):
        j = i + 1
        while j < len(lines2) and lines2[j].startswith('  '):
            j += 1
        insert_at = j
        break
assert insert_at is not None, 'точка вставки (после буллета Task 316) не найдена'
lines2.insert(insert_at, entry)
src = '\n'.join(lines2)
print('Буллет Task 317 вставлен (после Task 316)')

with open('Системный_промт_для_приложения_КИПиА.md', 'w', encoding='utf-8') as f:
    f.write(src)
print('Готово: системный промт — post-Task 317 (кэш v556, 1650 тестов)')
